"""Simple Unicode-aware word counting."""

import re

import config


def count_words(text: str, case_sensitive: bool = config.DEFAULT_CASE_SENSITIVE) -> dict[str, int]:
    """Return a dictionary containing the frequency of each word in *text*."""
    if not case_sensitive:
        text = text.casefold()

    counts: dict[str, int] = {}
    for word in re.findall(r"\b\w+\b", text):
        counts[word] = counts.get(word, 0) + 1
    return counts

