"""wordcount 核心逻辑的单元测试。"""

import unittest

import config
from wordcount import count_words


class TestCountWords(unittest.TestCase):
    def test_counts_repeated_words_and_punctuation(self) -> None:
        text = "Hello, world! Hello again; the world awaits."
        self.assertEqual(
            count_words(text),
            {"Hello": 2, "world": 2, "again": 1, "the": 1, "awaits": 1},
        )

    def test_case_sensitive_by_default(self) -> None:
        self.assertTrue(config.DEFAULT_CASE_SENSITIVE)
        self.assertEqual(
            count_words("Word word WORD"),
            {"Word": 1, "word": 1, "WORD": 1},
        )

    def test_case_insensitive_counting(self) -> None:
        self.assertEqual(
            count_words("Word word WORD", case_sensitive=False),
            {"word": 3},
        )

    def test_unicode_words_numbers_and_underscores(self) -> None:
        text = "你好，世界！你好 café CAFÉ café_1 42 42"
        self.assertEqual(
            count_words(text),
            {"你好": 2, "世界": 1, "café": 1, "CAFÉ": 1, "café_1": 1, "42": 2},
        )

    def test_empty_text(self) -> None:
        self.assertEqual(count_words(""), {})


if __name__ == "__main__":
    unittest.main()

